import{_ as s,o,c as a,a3 as t}from"./chunks/framework._nQ7I0JF.js";const u=JSON.parse('{"title":"The websites share one Vue and DaisyUI design system","description":"","frontmatter":{"status":"accepted","date":"2026-11-07T00:00:00.000Z"},"headers":[],"relativePath":"docs/adr/0023-the-websites-share-one-vue-and-daisyui-design-system.md","filePath":"docs/adr/0023-the-websites-share-one-vue-and-daisyui-design-system.md"}'),n={name:"docs/adr/0023-the-websites-share-one-vue-and-daisyui-design-system.md"};function i(d,e,c,r,h,l){return o(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="the-websites-share-one-vue-and-daisyui-design-system" tabindex="-1">The websites share one Vue and DaisyUI design system <a class="header-anchor" href="#the-websites-share-one-vue-and-daisyui-design-system" aria-label="Permalink to &quot;The websites share one Vue and DaisyUI design system&quot;">​</a></h1><p>The landing site, the web app (<a href="./0021-the-landing-site-the-app-and-the-api-have-their-own-hostname">ADR 0021</a>), the web mockups and the docs site draw with one package, <code>web/ui</code> (<code>@coach-poulpy/ui</code>). It is <a href="https://daisyui.com" target="_blank" rel="noreferrer">DaisyUI 5</a> on Tailwind CSS 4 with one Poulpy theme, a few <code>cp-*</code> classes for the shapes DaisyUI lacks, and thin Vue components named after the <a href="./../design-system#components">design system</a>&#39;s table (<code>CpButton</code>, <code>CpChip</code>, <code>CpSearchField</code>, <code>CpSelectField</code>, <code>CpStepper</code>, <code>CpPoulpy</code>, <code>CpPoulpyCard</code>, <code>CpErrorNote</code>, <code>CpSheet</code>). The class names are the contract: a Vue component renders them, and a plain-HTML web mockup writes them. DaisyUI&#39;s classes carry the <code>cp-</code> prefix (<code>cp-btn cp-btn-primary</code>), so every class of the design system reads as ours, and our own classes never reuse a DaisyUI name.</p><h2 id="how-it-fits-together" tabindex="-1">How it fits together <a class="header-anchor" href="#how-it-fits-together" aria-label="Permalink to &quot;How it fits together&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>design/tokens.json ──build-tokens.mjs──▶ web/ui/src/tokens.css   (--cp-*, light and dark)</span></span>
<span class="line"><span>web/ui/src/theme.css                     DaisyUI&#39;s colours, radii and sizes point at --cp-*</span></span>
<span class="line"><span>web/ui/src/components/*.vue              the Vue components</span></span>
<span class="line"><span>web/ui/build-css.mjs ──▶ web/ui/poulpy-ui.css        prebuilt, for web mockups (generated)</span></span>
<span class="line"><span>                    └──▶ web/ui/poulpy-ui-embed.css  no page-wide rule, for the docs site (generated)</span></span>
<span class="line"><span>web/app                                  imports tokens.css and theme.css into its own Tailwind build</span></span></code></pre></div><ul><li><strong>One theme, light and dark from the tokens.</strong> DaisyUI&#39;s variables are <code>var(--cp-*)</code> references, so <code>tokens.css</code> alone switches light and dark (system setting, or <code>data-theme=&quot;light&quot;</code> / <code>&quot;dark&quot;</code> on <code>&lt;html&gt;</code>), as it does for the mockups today. There is no second copy of the palette to drift from <code>design/tokens.json</code> (<a href="./0012-design-tokens-generated-from-one-file">ADR 0012</a>).</li><li><strong>The roles map onto DaisyUI&#39;s names</strong>: <code>primary</code> stays primary, <code>primaryContainer</code> is secondary (tonal), <code>grumpy</code> is accent, <code>surface</code>, <code>background</code> and <code>surfaceVariant</code> are base-100, 200 and 300. DaisyUI&#39;s warning is set to the error colour, because ember never means a warning.</li><li><strong>Web mockups stay plain HTML</strong> (<a href="./0016-mockups-are-plain-html-in-the-repo">ADR 0016</a>). They link <code>tokens.css</code> and the prebuilt <code>poulpy-ui.css</code>, and need no browser-side build. Tailwind keeps only the classes it finds in the components and in <code>design/mockups/*/web/</code>; the web build generates both CSS files from source, and the docs-site build copies the mockup stylesheet into its published assets. Generated CSS is ignored by Git and is never committed.</li><li><strong>The docs site shows the real components</strong> on its Web components page, from source, with the embed build: no reset, no root colours, so the site keeps its own look. Each sample panel pins a theme with a <code>cp-theme-light</code> or <code>cp-theme-dark</code> class from <code>tokens.css</code>.</li></ul><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to &quot;Why&quot;">​</a></h2><ul><li>The websites, the mockups that describe them and the docs that show them cannot drift apart when they share one set of classes.</li><li>DaisyUI gives accessible, ready-made forms, dialogs and menus as plain classes, which plain-HTML mockups can use with no JavaScript; a Vue-only library could not be drawn in a mockup.</li><li>Pointing the theme at the existing <code>--cp-*</code> variables keeps <code>design/tokens.json</code> the only place a colour is chosen.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Phone and tablet mockups stay on <code>design/mockups/shared/mockup.css</code>, because they draw the native Compose and SwiftUI screens, which DaisyUI&#39;s look does not match (chosen by the owner on 7 November 2026). Only <code>web/</code> mockups use the shared CSS.</li><li><code>web/</code> is an npm workspace: <code>web/ui</code> and <code>web/app</code> today, <code>web/landing</code> when the landing site is written. <code>tokens.css</code> moved from <code>web/src/styles/</code> to <code>web/ui/src/</code>.</li><li>DaisyUI and Tailwind are pinned to exact versions so builds produce reproducible CSS; upgrading them is a PR that regenerates the build output.</li><li>A component the websites need goes in <code>web/ui</code> with its classes on the <a href="https://tkint.github.io/coach-poulpy/web-components" target="_blank" rel="noreferrer">Web components</a> page, never as one-off styles in an app.</li></ul>`,9)])])}const m=s(n,[["render",i]]);export{u as __pageData,m as default};
